WITH ranked AS (SELECT * FROM shipments QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id, carrier ORDER BY delivered_date, id) = 1) SELECT carrier, COUNT_IF(carrier = 'DHL') AS dhl_events, APPROX_PERCENTILE(cost, 0.5) AS cost_p50, SUM(cost) FILTER (WHERE status = 'DELIVERED') AS delivered_total_cost, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN carrier = 'Flash' THEN 1 END), 0), 2) AS cost_per_flash FROM ranked GROUP BY carrier ORDER BY cost_per_flash NULLS FIRST
